function toggleMenu(){const e=document.getElementById('mobile-menu'),t=document.querySelector('[aria-controls="mobile-menu"]');if(!e)return;const n=!1===e.classList.toggle('hidden');t&&t.setAttribute('aria-expanded',n?'true':'false')}function toggleSubMenu(e){const t=document.getElementById(e);if(!t)return;const n=t.previousElementSibling,o=n?n.querySelector('i'):null,s=!1===t.classList.toggle('hidden');n&&n.setAttribute('aria-expanded',s?'true':'false'),o&&(o.classList.toggle('fa-plus',!s),o.classList.toggle('fa-minus',s))}window.addEventListener('resize',function(){const e=document.getElementById('mobile-menu');if(e&&window.innerWidth>=768&&!e.classList.contains('hidden')){e.classList.add('hidden');const t=document.querySelector('[aria-controls="mobile-menu"]');t&&t.setAttribute('aria-expanded','false')}});
